"""Compare qualified Linux guest state across packaged and paired artifacts."""

import argparse
import hashlib
import json
from pathlib import Path


WITNESS_KEYS = (
    "raw_icount", "logical_tick", "idle_wake_tick", "registers",
    "ram_sha256", "ram_bytes", "serial_sha256", "markers", "advances", "status",
    "timer_witness", "device_projection_manifest",
)


def load(path):
    return json.loads(path.read_text())


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--packaged-result", type=Path, required=True)
    parser.add_argument("--scheduled-results", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    arguments = parser.parse_args()
    packaged = load(arguments.packaged_result)
    scheduled_paths = sorted(arguments.scheduled_results.glob("pair-*/trial/results.json"))
    assert len(scheduled_paths) == 14
    expected = {key: packaged["witness"][key] for key in WITNESS_KEYS}
    sources = [packaged] + [load(path) for path in scheduled_paths]

    for source in sources:
        assert source["deterministic"] is True
        assert source["configuration"] == packaged["configuration"]
        for key in ("kernel_sha256", "initrd_sha256"):
            assert source["guest"][key] == packaged["guest"][key]
        for sample in source["samples"]:
            assert {key: sample[key] for key in WITNESS_KEYS} == expected

    scheduled_artifacts = {}
    for source in sources[1:]:
        for label, artifact in source["artifacts"].items():
            hashes = {key: artifact[key] for key in ("qemu_sha256", "plugin_sha256")}
            assert label not in scheduled_artifacts or scheduled_artifacts[label] == hashes
            scheduled_artifacts[label] = hashes

    evidence = {
        "status": "PASS",
        "scope": "Guest-state equality across both normal packaged qualification runs and all fourteen literal-original/final manual-plugin timing runs; qualification timing is excluded.",
        "packaged_samples": len(packaged["samples"]),
        "scheduled_samples": sum(len(source["samples"]) for source in sources[1:]),
        "witness_fields_compared": list(WITNESS_KEYS),
        "guest_artifacts": {key: packaged["guest"][key] for key in ("kernel_sha256", "initrd_sha256")},
        "configuration": packaged["configuration"],
        "witness": expected,
        "packaged_artifacts": {
            label: {key: artifact[key] for key in ("qemu_sha256", "plugin_sha256")}
            for label, artifact in packaged["artifacts"].items()
        },
        "scheduled_artifacts": scheduled_artifacts,
        "scheduled_artifact_hashes_identical_per_label": True,
        "comparison_script_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    }
    serialized = json.dumps(evidence, indent=2) + "\n"
    arguments.output.write_text(serialized)
    print("PASS: 2 packaged and 14 scheduled Linux witnesses exactly equal")


if __name__ == "__main__":
    main()

