final_fixture_fresh_aggregate_cached_ove.qualification_wrapper_source:
{fixtureSource, qualifiedSource}: let
  fixtureRoot = builtins.toPath fixtureSource;
  qualifiedRoot = builtins.toPath qualifiedSource;
  qualified = import (qualifiedRoot + "/default.nix") {};
  inherit (qualified) pkgs lib;

  # Regenerate aggregate provenance for the corrected fixture source while
  # retaining the byte-identical, fully checked production executables.
  correctedSuite = pkgs.callPackage (fixtureRoot + "/pkgs/tools/crucible/crucible.nix") {
    mkCargoPackage = arguments:
      if arguments.pname == "crucible-controller"
      then pkgs.crucible-controller
      else if arguments.pname == "crucible-debug-gateway"
      then pkgs.crucible.passthru.debugGateway
      else throw "Unexpected compiled package in fixture-only qualification";
  };
in {
  # Fixture-only corrections use already qualified, identical runtime inputs.
  checks.crucible = {
    phase1.gates.licenseBoundary.rawGate = import (fixtureRoot + "/tests/crucible/phase1-license-boundary.nix") {
      inherit pkgs lib;
    };
    phase7 = {
      crucibleQemuPackage = import (fixtureRoot + "/tests/crucible/phase7-crucible-qemu-package.nix") {
        inherit pkgs lib;
      };
      cruciblePackageAbiVersioning = import (fixtureRoot + "/tests/crucible/phase7-crucible-package-abi-versioning.nix") {
        inherit pkgs lib;
      };
      crucibleReleaseManifest = import (fixtureRoot + "/tests/crucible/phase7-crucible-release-manifest.nix") {
        inherit pkgs lib;
        cruciblePackage = correctedSuite;
      };
    };
  };
}
